function patchUiSource(source){
 const actual=require('node:crypto').createHash('sha256').update(source).digest('hex');
 if(actual!==UI_RENDERER_SHA256)return {applied:false,reason:'Unreviewed UI renderer SHA-256',source};
 for(const p of UI_SOURCE_PATCHES)if(source.slice(p.start,p.end)!==p.from)return {applied:false,reason:'UI span mismatch at '+p.start,source};
 const parts=[];let end=0;for(const p of UI_SOURCE_PATCHES){parts.push(source.slice(end,p.start),p.to);end=p.end;}parts.push(source.slice(end));const output=parts.join('');
 return {applied:true,count:UI_SOURCE_PATCHES.length,source:output};
}

