function patchBundle(source) {
  if (typeof source !== 'string') throw new TypeError('Bundle must be a string');
  const ui = patchUiSource(source);
  if (!ui.applied) return { applied: false, structuralApplied: false, reason: ui.reason, source };
  let output = ui.source;
  for (const marker of CONTEXTUAL_PATCHES) {
    if (occurrenceCount(output, marker.from) !== marker.expectedCount) return {applied:false,structuralApplied:false,reason:"Context mismatch: "+marker.name,source};
    output=output.replaceAll(marker.from,marker.to);
  }

  // 1. Validate and apply Critical Structural Patches atomically
  for (const marker of STRUCTURAL_MARKERS) {
    if (occurrenceCount(output, marker.from) !== 1) {
      return {
        applied: false,
        structuralApplied: false,
        reason: 'Unexpected structural bundle shape: ' + marker.name,
        source
      };
    }
  }
  for (const marker of STRUCTURAL_MARKERS) {
    output = output.replace(marker.from, marker.to);
  }

  // 2. Validate and apply Independent UI Text Patches gracefully
  const appliedTextMarkers = [];
  const skippedTextMarkers = [];

  for (const marker of TEXT_MARKERS) {
    const count = occurrenceCount(output, marker.from);
    const expectedCount = marker.expectedCount || 1;
    if (count === expectedCount) {
      output = output.replaceAll(marker.from, marker.to);
      appliedTextMarkers.push(marker.name);
    } else {
      skippedTextMarkers.push({
        name: marker.name,
        reason: count === 0 ? 'Not found' : `Expected ${expectedCount} occurrences, found ${count}`
      });
    }
  }

  return {
    applied: true,
    structuralApplied: true,
    uiSourceCount: ui.count,
    contextualCount: CONTEXTUAL_PATCHES.length,
    appliedTextMarkers,
    skippedTextMarkers,
    source: output
  };
}

module.exports = {
  patchBundle,
  patchUiSource,
  UI_SOURCE_PATCHES,
  CONTEXTUAL_PATCHES,
  STRUCTURAL_MARKERS,
  TEXT_MARKERS,
  MARKERS
};
